}
const facts = { name: persona.display_name, risk_month: 'February', risk_week_start: risk.week_start, shortfall: risk.shortfall,
  bills: risk.drivers.filter(d => d.type === 'bill').map(d => ({ label: d.label, amount: d.amount, date: d.date })),
