const call_id = persona.persona_id + '_' + language + '_' + risk.id;
const shell = { call_id, language, dir: LANGS[language].dir, caller_label: 'Future You · February 2027',
  disclosure_text: LANGS[language].disclosure, mime: 'audio/mpeg', risk_id: risk.id,
